import sqlite3


def get_user(conn: sqlite3.Connection, user_id: str):
    cursor = conn.cursor()
    cursor.execute(f"SELECT * FROM users WHERE id = {user_id}")
    return cursor.fetchone()

import sqlite3


def get_user(conn: sqlite3.Connection, user_id: int):
    cursor = conn.execute("SELECT id, name FROM users WHERE id = ?", (user_id,))
    return cursor.fetchone()

from django.http import JsonResponse

from shop.models import Order


def order_list(request):
    data = []
    for order in Order.objects.all():
        data.append({"id": order.id, "customer": order.customer.name})
    return JsonResponse({"orders": data})

export function renderSearch(container) {
  const params = new URLSearchParams(window.location.search);
  const term = params.get("q");
  container.innerHTML = `<h2>Results for ${term}</h2>`;
}

import { api } from "./api";

export async function saveAndRedirect(settings: Record<string, string>): Promise<void> {
